from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        _, wtime = cache[key]
        return t >= wtime + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        if kind == 'put':
            value = op[3]
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
                    # now treat as absent
                    if len(cache) >= capacity:
                        cache.popitem(last=False)
                    cache[key] = (value, t)
                else:
                    cache[key] = (value, t)
                    cache.move_to_end(key)
            else:
                if len(cache) >= capacity:
                    cache.popitem(last=False)
                cache[key] = (value, t)

        elif kind == 'get':
            if key in cache:
                if is_expired(key, t):
                    del cache[key]
                    results.append(-1)
                else:
                    value, wtime = cache[key]
                    cache.move_to_end(key)
                    results.append(value)
            else:
                results.append(-1)

    return results

